"""Evaluation helpers. Labels are consumed ONLY here, after scores exist (R9, R10)."""
import numpy as np
from sklearn.metrics import average_precision_score, precision_recall_curve, roc_auc_score


def auc_roc(y, scores):
    return float(roc_auc_score(y, scores))


def auc_pr_ap(y, scores):
    """Primary AUC-PR: average precision (ADBench convention)."""
    return float(average_precision_score(y, scores))


def auc_pr_trapz(y, scores):
    """Secondary AUC-PR: trapezoidal area under the precision-recall curve."""
    p, r, _ = precision_recall_curve(y, scores)
    order = np.argsort(r)
    return float(np.trapezoid(p[order], r[order]))


def evaluate_scores(y, scores):
    return {
        "auc_roc": auc_roc(y, scores),
        "auc_pr_ap": auc_pr_ap(y, scores),
        "auc_pr_trapz": auc_pr_trapz(y, scores),
    }


def summarize(values):
    v = np.asarray(values, dtype=np.float64)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=0)),
        "std_ddof1": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
        "values": [float(x) for x in v],
    }

